/**
 * 流式语音识别器
 * 支持两种音频来源：
 * 1. 麦克风录音（实时）
 * 2. 音频文件（模拟流式）
 *
 * 参考：
 * - byted-ailab-speech-sdk 的录音和协议处理
 */




// ==================== 常量定义 ====================
const ASR_CONSTANTS = {
  PROTOCOL_VERSION: 0b0001,
  DEFAULT_HEADER_SIZE: 0b0001,
  // 消息类型
  CLIENT_FULL_REQUEST: 0b0001,
  CLIENT_AUDIO_ONLY_REQUEST: 0b0010,
  SERVER_FULL_RESPONSE: 0b1001,
  SERVER_ACK: 0b1011,
  SERVER_ERROR_RESPONSE: 0b1111,
  // 消息类型特定标志
  NO_SEQUENCE: 0b0000,
  POS_SEQUENCE: 0b0001,
  NEG_WITHOUT_SEQUENCE: 0b0010,
  NEG_WITH_SEQUENCE: 0b0011,
  MESSAGE_WITH_EVENT: 0b0100,
  // 消息序列化
  NO_SERIALIZATION: 0b0000,
  JSON: 0b0001,
  THRIFT: 0b0011,
  // 消息压缩
  NO_COMPRESSION: 0b0000,
  GZIP: 0b0001
};

// ==================== 工具函数 ====================

/**
 * Base64 转 ArrayBuffer
 */
function recorder_stream_base64ToArrayBuffer(base64) {
  const binaryString = window.atob(base64);
  const length = binaryString.length;
  const bytes = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

/**
 * ArrayBuffer 转 UTF-8 字符串
 */
function recorder_stream_arrayBufferToString(buffer) {
  return new TextDecoder('utf-8').decode(buffer);
}

/**
 * AES-GCM 解密
 */
async function recorder_stream_decryptAESGCM(cipherTextBase64) {
  const keyBase64 = '8qMUnKpoNkAXlQQNqTWfawAbtw0g+rphbbnCIb+aKX4=';
  try {
    const cipherTextArrayBuffer = recorder_stream_base64ToArrayBuffer(cipherTextBase64);
    const keyArrayBuffer = recorder_stream_base64ToArrayBuffer(keyBase64);
    const GCM_IV_LENGTH = 12;
    const iv = cipherTextArrayBuffer.slice(0, GCM_IV_LENGTH);
    const encryptedData = cipherTextArrayBuffer.slice(GCM_IV_LENGTH);
    const key = await window.crypto.subtle.importKey('raw', keyArrayBuffer, {
      name: 'AES-GCM'
    }, false, ['decrypt']);
    const decryptedArrayBuffer = await window.crypto.subtle.decrypt({
      name: 'AES-GCM',
      iv: iv,
      tagLength: 128
    }, key, encryptedData);
    return recorder_stream_arrayBufferToString(decryptedArrayBuffer);
  } catch (error) {
    console.error('解密失败:', error);
    throw new Error('解密过程中发生错误');
  }
}

/**
 * Blob 转 ArrayBuffer
 */
async function blobToArrayBuffer(blob) {
  return new Promise(resolve => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.readAsArrayBuffer(blob);
  });
}

/**
 * 生成协议 Header
 */
function generateHeader(messageType = ASR_CONSTANTS.CLIENT_FULL_REQUEST, version = ASR_CONSTANTS.PROTOCOL_VERSION, messageTypeSpecificFlags = ASR_CONSTANTS.NO_SEQUENCE, serialMethod = ASR_CONSTANTS.JSON, compressionType = ASR_CONSTANTS.NO_COMPRESSION, reservedData = 0x00) {
  const buffer = new ArrayBuffer(8);
  const dataView = new DataView(buffer);
  dataView.setUint8(0, version << 4 | 0x01); // header_size = 1
  dataView.setUint8(1, messageType << 4 | messageTypeSpecificFlags);
  dataView.setUint8(2, serialMethod << 4 | compressionType);
  dataView.setUint8(3, reservedData);
  dataView.setUint32(4, 0x00, false);
  return dataView;
}

/**
 * 编码完整客户端请求（配置信息）
 */
function encodeFullClientRequest(requestData) {
  const full_client_request_header = generateHeader();
  const json = JSON.stringify(requestData);
  const encoder = new TextEncoder();
  const jsonBytes = encoder.encode(json);

  // 在 header 的第 4 字节位置（bytes 4-7）设置 payload size
  full_client_request_header.setUint32(4, jsonBytes.length, false); // big-endian

  // 直接返回 Blob: header(8) + payload
  return new Blob([full_client_request_header.buffer, jsonBytes]);
}

/**
 * 编码纯音频请求
 * 完全参考 byted-ailab-speech-sdk 的实现
 * 接收 Blob、ArrayBuffer 或 TypedArray 类型
 */
function encodeAudioOnlyRequest(requestData) {
  const audio_only_request_header = generateHeader(ASR_CONSTANTS.CLIENT_AUDIO_ONLY_REQUEST);

  // 获取音频数据大小
  let size = 0;
  if (requestData instanceof Blob) {
    size = requestData.size;
  } else if (requestData instanceof ArrayBuffer) {
    size = requestData.byteLength;
  } else if (ArrayBuffer.isView(requestData)) {
    size = requestData.byteLength;
  }
  console.log(`encodeAudioOnlyRequest: 数据类型=${requestData.constructor.name}, 大小=${size} 字节`);
  audio_only_request_header.setUint32(4, size, false);

  // 将 DataView 转换为 Uint8Array，确保 Blob 正确处理
  const headerArray = new Uint8Array(audio_only_request_header.buffer);
  return new Blob([headerArray, requestData]);
}

/**
 * 编码停止请求（负包）
 */
function encodeStopRequest() {
  const stop_header = generateHeader(ASR_CONSTANTS.CLIENT_AUDIO_ONLY_REQUEST, ASR_CONSTANTS.PROTOCOL_VERSION, ASR_CONSTANTS.NEG_WITHOUT_SEQUENCE // 使用负包标志
  );

  // 在 header 的第 4 字节位置（bytes 4-7）设置 payload size 为 0
  stop_header.setUint32(4, 0, false);

  // 直接返回 Blob: header(8)
  return new Blob([stop_header.buffer]);
}

/**
 * 解析服务器响应
 */
async function parseResponse(res, hasSequence = false) {
  try {
    const arraybuffer = await blobToArrayBuffer(res);
    const dataView = new DataView(arraybuffer);

    // 解析 Header
    const byte0 = dataView.getUint8(0);
    const headerSizeInWords = byte0 & 0x0f;
    const headerSize = headerSizeInWords * 4;
    const byte1 = dataView.getUint8(1);
    const messageType = byte1 >> 4 & 0x0f;
    // const flags = byte1 & 0x0f

    // 计算 payload 起始位置
    let offset = headerSize;

    // 处理序列号（如果存在）
    if (hasSequence) {
      offset += 4; // 跳过序列号
    }

    // 错误响应：8byte描述字段
    const messageDescriptionLength = messageType === ASR_CONSTANTS.SERVER_ERROR_RESPONSE ? 8 : 4;
    offset += messageDescriptionLength;

    // 提取 payload
    const payloadBuffer = arraybuffer.slice(offset);
    const uint8Msg = new Uint8Array(payloadBuffer);
    const enc = new TextDecoder('utf-8');
    const text = enc.decode(uint8Msg);
    try {
      /* 可能会抛出异常的代码块 */
      const payload = JSON.parse(text);
      return payload;
    } catch (error) {
      /* 处理异常的代码块 */
      throw text;
    }
  } catch (error) {
    console.error('解析响应失败:', error);
    throw error;
  }
}

